"""Reversible performance preset tests with SharedPreferences/network stubs; no Gradle/emulator."""
import pathlib, subprocess, tempfile
root=pathlib.Path(__file__).resolve().parents[2]
stubs={
'android/content/SharedPreferences.java':'''package android.content;import java.util.*;public class SharedPreferences{public Map<String,Object> values=new HashMap<>();public boolean contains(String k){return values.containsKey(k);}public int getInt(String k,int d){return values.get(k) instanceof Integer?(Integer)values.get(k):d;}public boolean getBoolean(String k,boolean d){return values.get(k) instanceof Boolean?(Boolean)values.get(k):d;}public String getString(String k,String d){return values.get(k) instanceof String?(String)values.get(k):d;}public Editor edit(){return new Editor();}public class Editor{public Editor putInt(String k,int v){values.put(k,v);return this;}public Editor putBoolean(String k,boolean v){values.put(k,v);return this;}public Editor putString(String k,String v){values.put(k,v);return this;}public Editor remove(String k){values.remove(k);return this;}public void apply(){}}}''',
'android/content/Context.java':'package android.content;public class Context{public static final String CONNECTIVITY_SERVICE="network";public Object getSystemService(String service){return android.net.ConnectivityManager.instance;}}',
'android/net/ConnectivityManager.java':'package android.net;public class ConnectivityManager{public static ConnectivityManager instance=new ConnectivityManager();public static boolean connected=true,metered,fail;public ConnectivityManager getActiveNetworkInfo(){if(fail)throw new SecurityException();return this;}public boolean isConnected(){return connected;}public boolean isActiveNetworkMetered(){return metered;}}',
'org/telegram/messenger/ApplicationLoader.java':'package org.telegram.messenger;public class ApplicationLoader{public static android.content.Context applicationContext=new android.content.Context();}',
'org/telegram/messenger/MessagesController.java':'package org.telegram.messenger;public class MessagesController{public static android.content.SharedPreferences prefs=new android.content.SharedPreferences();public static android.content.SharedPreferences getGlobalMainSettings(){return prefs;}}',
'org/telegram/messenger/SharedConfig.java':'package org.telegram.messenger;public class SharedConfig{public static boolean animations=true;public static boolean animationsEnabled(){return animations;}public static void setAnimationsEnabled(boolean value){animations=value;}}',
'org/telegram/messenger/LiteMode.java':'''package org.telegram.messenger;public class LiteMode{public static final int FLAGS_ANIMATED_STICKERS=3,FLAGS_ANIMATED_EMOJI=12,FLAG_CHAT_BACKGROUND=16,FLAG_CHAT_SPOILER=32,FLAG_CHAT_BLUR=64,FLAG_CHAT_SCALE=128,FLAG_CHAT_THANOS=256,FLAG_CALLS_ANIMATIONS=512,FLAG_AUTOPLAY_VIDEOS=1024,FLAG_AUTOPLAY_GIFS=2048,FLAG_PARTICLES=4096,FLAG_LIQUID_GLASS=8192,PRESET_HIGH=8191;public static int loaded;public static int getValue(boolean ignore){return MessagesController.prefs.getInt("lite_mode6",PRESET_HIGH);}public static void loadPreference(){loaded++;}}''',
'org/telegram/utils/proxy/PreviewNetworkPolicy.java':'package org.telegram.utils.proxy;import org.telegram.messenger.MessagesController;public class PreviewNetworkPolicy{public static boolean wifiOnly(){return MessagesController.prefs.getBoolean("amp_unmetered_only",false);}}',
'org/telegram/ui/skins/MotionController.java':'package org.telegram.ui.skins;public class MotionController{static MotionStyle style=MotionStyle.ORIGINAL;public static MotionStyle getStyle(){return style;}public static void setStyle(MotionStyle s){style=s;}}',
'PerformanceTest.java':'''import org.telegram.messenger.*;import org.telegram.ui.skins.*;import org.telegram.utils.proxy.*;import android.net.*;public class PerformanceTest{static void ck(boolean b,String s){if(!b)throw new AssertionError(s);}public static void main(String[]args){
int outside=1<<20,otherOutside=1<<21,inside=LiteMode.FLAG_CHAT_SPOILER|LiteMode.FLAG_AUTOPLAY_GIFS|LiteMode.FLAG_LIQUID_GLASS;MessagesController.prefs.edit().putInt("lite_mode6",outside|inside).apply();MotionController.setStyle(MotionStyle.FADE);ck(CommunityPerformanceSettings.allowPreload(),"unset preserves original behavior");
CommunityPerformanceSettings.apply(CommunityPerformanceSettings.SAVING);ck(CommunityPerformanceSettings.canUndo(),"undo offered");ck(LiteMode.getValue(true)==outside,"saving only clears controlled mask");ck(!SharedConfig.animationsEnabled()&&MotionController.getStyle()==MotionStyle.NONE&&PreviewNetworkPolicy.wifiOnly()&&!CommunityPerformanceSettings.allowPreload(),"saving policy");
MessagesController.prefs.edit().putInt("lite_mode6",outside|otherOutside).apply();CommunityPerformanceSettings.undo();ck(LiteMode.getValue(true)==(outside|otherOutside|inside),"undo preserves new external flag");ck(SharedConfig.animationsEnabled()&&MotionController.getStyle()==MotionStyle.FADE&&!PreviewNetworkPolicy.wifiOnly()&&CommunityPerformanceSettings.allowPreload(),"undo restores settings");ck(!CommunityPerformanceSettings.canUndo(),"backup cleared");int flags=LiteMode.getValue(true);CommunityPerformanceSettings.undo();ck(flags==LiteMode.getValue(true),"undo without backup no-op");
CommunityPerformanceSettings.apply(CommunityPerformanceSettings.BALANCED);ck(LiteMode.getValue(true)==(outside|otherOutside|LiteMode.FLAGS_ANIMATED_STICKERS|LiteMode.FLAG_AUTOPLAY_GIFS),"balanced mask");ConnectivityManager.metered=false;ConnectivityManager.connected=true;ck(CommunityPerformanceSettings.allowPreload(),"balanced unmetered");ConnectivityManager.metered=true;ck(!CommunityPerformanceSettings.allowPreload(),"balanced metered denied");ConnectivityManager.metered=false;ConnectivityManager.connected=false;ck(!CommunityPerformanceSettings.allowPreload(),"balanced disconnected denied");ConnectivityManager.connected=true;ConnectivityManager.fail=true;ck(!CommunityPerformanceSettings.allowPreload(),"balanced unknown network denied");ConnectivityManager.fail=false;
CommunityPerformanceSettings.apply(CommunityPerformanceSettings.FLUID);ck((LiteMode.getValue(true)&LiteMode.FLAG_LIQUID_GLASS)!=0,"fluid enables glass preference");ConnectivityManager.metered=true;ck(CommunityPerformanceSettings.allowPreload()&&!PreviewNetworkPolicy.wifiOnly()&&MotionController.getStyle()==MotionStyle.SMOOTH,"fluid permits existing downloader policy");CommunityPerformanceSettings.undo();ck(MotionController.getStyle()==MotionStyle.QUICK&&!CommunityPerformanceSettings.allowPreload(),"undo last apply returns balanced not initial");
boolean invalid=false;try{CommunityPerformanceSettings.apply(99);}catch(IllegalArgumentException expected){invalid=true;}ck(invalid,"invalid profile rejected");System.out.println("Performance apply/undo, mask preservation and preload policy tests passed");}}
'''
}
with tempfile.TemporaryDirectory(prefix='performance-tests-') as tmp:
 paths=[]
 for name,text in stubs.items():
  p=pathlib.Path(tmp,name);p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text,encoding='utf-8');paths.append(str(p))
 paths += [str(root/'TMessagesProj/src/main/java/org/telegram/messenger/CommunityPerformanceSettings.java'),str(root/'TMessagesProj/src/main/java/org/telegram/ui/skins/MotionStyle.java')]
 subprocess.run(['javac','-encoding','UTF-8','-d',tmp,*paths],check=True)
 subprocess.run(['java','-cp',tmp,'PerformanceTest'],check=True)
